const clips={"engine": "", "skid": "", "shot": "", "voice": ""};

(() => {
  'use strict';
  let ctx, master, enabled=false, ready=false, lastVoice=-10;
  const buffers={}, loops={}, voices=new Set();
  function loop(name) {
    const source=ctx.createBufferSource(), gain=ctx.createGain();
    source.buffer=buffers[name]; source.loop=true; gain.gain.value=0;
    source.connect(gain).connect(master); source.start();
    return {source,gain};
  }
  window.HarborAudio={
    start(context) {
      if(ctx || !context?.decodeAudioData || !context?.createBufferSource) return;
      ctx=context; master=ctx.createGain(); master.gain.value=0; master.connect(ctx.destination);
      Promise.all(Object.entries(clips).map(async([name,data])=>{
        const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));
        buffers[name]=await ctx.decodeAudioData(bytes.buffer);
      })).then(()=>{loops.engine=loop('engine');loops.traffic=loop('engine');loops.skid=loop('skid');ready=true;}).catch(()=>{});
    },
    update(state) {
      enabled=state.enabled;
      if(!master)return;
      const now=ctx.currentTime;
      master.gain.setTargetAtTime(enabled?.7:0,now,.025);
      if(!enabled){ for(const source of voices){try{source.stop();}catch{}} voices.clear(); }
      if(!ready)return;
      loops.engine.gain.gain.setTargetAtTime(state.driving?.18:0,now,.06);
      loops.engine.source.playbackRate.setTargetAtTime(.75+Math.abs(state.speed)*.085,now,.09);
      loops.traffic.gain.gain.setTargetAtTime(state.trafficVolume*.12,now,.12);
      loops.traffic.source.playbackRate.setTargetAtTime(.8+Math.abs(state.trafficSpeed)*.06,now,.1);
      loops.skid.gain.gain.setTargetAtTime(state.braking?.16:0,now,.05);
    },
    play(name,rate=1) {
      if(!ready || !enabled || voices.size>=8 || !buffers[name])return false;
      if(name==='voice' && ctx.currentTime-lastVoice<2)return false;
      if(name==='voice')lastVoice=ctx.currentTime;
      const source=ctx.createBufferSource();source.buffer=buffers[name];source.playbackRate.value=rate;
      source.connect(master);voices.add(source);source.onended=()=>{voices.delete(source);source.disconnect();};source.start();return true;
    },
    ready:()=>ready
  };
})();
